def control(obs):
    h = obs.get('hitch_deg', 0.0)
    t = obs.get('t', 0.0)
    st = obs.get('status')
    if st in ('JACKKNIFED', 'PINNED') or abs(h) > 55:
        return (0.0, 0.8)
    bias = 3.0 if t < 8.0 else 0.0
    steer = 2.5 * h + bias
    steer = max(-34.0, min(34.0, steer))
    return (steer, -1.0)

