def control(obs):
    t = obs.get('t', 0.0)
    dt = obs.get('dt', 0.1)
    h = obs.get('hitch_deg', 0.0)
    st = obs.get('status')
    v = obs.get('motion', {}).get('v_mps', 0.0)
    ph = S['phase']
    if ph == 'rev':
        if st in ('PINNED', 'JACKKNIFED') or abs(h) > 55:
            S['phase'] = 'fwd'
            S['acc'] = 0.0
            ph = 'fwd'
        else:
            return (max(-34.0, min(34.0, 2.5 * h)), -0.8)
    if ph == 'rev2' and st in ('PINNED', 'JACKKNIFED'):
        S['phase'] = 'fwd'
        S['acc'] = 0.0
        ph = 'fwd'
    if ph == 'fwd':
        if v > 0.2:
            S['acc'] += dt
        if S['acc'] < 1.5:
            return (0.0, 0.6)
        S['phase'] = 'rev2'
        S['t1'] = t
    bias = 8.0 if t - S['t1'] < 4.0 else 0.0
    return (max(-34.0, min(34.0, 2.5 * h + bias)), -0.8)

