PH = 'clear'
T0 = None

def control(obs):
    global PH, T0
    st = obs.get('status')
    t = float(obs.get('t', 0.0))
    hitch = float(obs.get('hitch_deg', 0.0))
    rear = obs.get('rig', {}).get('trailer_rear', [0.0, 0.0])
    y = float(rear[1])
    if T0 is None:
        T0 = t
    if st in ('JACKKNIFED', 'PINNED') and PH == 'rev':
        PH = 'clear'
        T0 = t
    if PH == 'clear':
        if y <= -0.3 or t - T0 > 6.0:
            PH = 'rev'
        else:
            return (5.0, 0.6)
    target = max(-12.0, min(12.0, -4.0 * (y + 0.3)))
    steer = 1.5 * (hitch - target)
    steer = max(-42.0, min(42.0, steer))
